public function store(Request $request)
{
    $order = Order::create($request->validated());

    Mail::to($order->email)->send(new OrderPlaced($order));
    Http::post('https://erp.internal/orders', $order->toArray());

    return response()->json($order, 201);
}

$rows = DB::select(
